import{_ as e,c as o,o as t,a4 as i}from"./chunks/framework.D5y910bP.js";const u=JSON.parse('{"title":"Cloudflare Hotlink Protection (403 on Cross-Origin Images)","description":"","frontmatter":{"date":"2024-07-20T00:00:00.000Z","tags":["cloudflare","hotlink protection","cross-origin","images","cors"],"title":"Cloudflare Hotlink Protection (403 on Cross-Origin Images)"},"headers":[],"relativePath":"blog/cf-hotlink-cross-origin-images.md","filePath":"blog/cf-hotlink-cross-origin-images.md","lastUpdated":1739289997000}'),s={name:"blog/cf-hotlink-cross-origin-images.md"},a=i('<h1 id="cloudflare-hotlink-protection-403-on-cross-origin-images" tabindex="-1">Cloudflare Hotlink Protection (403 on Cross-Origin Images) <a class="header-anchor" href="#cloudflare-hotlink-protection-403-on-cross-origin-images" aria-label="Permalink to &quot;Cloudflare Hotlink Protection (403 on Cross-Origin Images)&quot;">​</a></h1><p>There&#39;s a new feature in Cloudflare websites - Scrape Shield. This feature is used to protect the website from scraping.</p><p>Cloudflare show&#39;s a banner to enable the free feature on websites.</p><p>This also includes a feature <a href="https://developers.cloudflare.com/waf/tools/scrape-shield/hotlink-protection/" target="_blank" rel="noreferrer">Hotlink Protection</a> that prevents images from being used by other sites.</p><p>Enabling it breaks all the workers and buckets mapped to the domain/subdomain in the zone that are serving any kind of images of type - gif, ico, jpg, jpeg, and png.</p><p>Requesting any image URL from the domain results in a <code>403 Forbidden error with no CORS headers</code>.</p><p>Note that this only happens for images, not for other files like glb, js, css, pdf etc. So this only breaks parts of apps that you serve.</p><p>To fix, disable hotlink protection or scrape shield for the website or add a <a href="https://developers.cloudflare.com/rules/configuration-rules/" target="_blank" rel="noreferrer">Configuration Rule</a> to disable it selectively.</p><ul><li>Go to website in cloudflare dashboard</li><li>Rules -&gt; Configuration rules</li><li>Add a new rule</li><li>Set filter like</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(http.host in {&quot;assets.example.com&quot; &quot;assets.drive.example.com&quot;})</span></span></code></pre></div><ul><li>Add <code>Hotlink Protection</code> setting and set to Toggle to Off.</li><li>Save and Deploy</li></ul>',11),r=[a];function n(l,c,d,p,h,g){return t(),o("div",null,r)}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
